-- Catalogues repris de l'application de bureau (référentiel marocain des médicaments, analyses, imagerie).
-- Généré depuis le dump du bureau : aucune donnée de patient.

CREATE TEMP TABLE import_medicament (id int, ean bigint, nom text, dci text, forme text, presentation text,
    ppv double precision, pbr double precision, ph double precision, pbrh double precision, classe text, pg text) ON COMMIT DROP;
-- Le catalogue du bureau contient des doublons (même médicament importé plusieurs fois) : un seul gardé.
SELECT 'MA', nom, dci, forme, presentation, classe, prix FROM (
  SELECT DISTINCT ON (lower(btrim(nom)), lower(coalesce(btrim(dci), '')), lower(coalesce(btrim(forme), '')), lower(coalesce(btrim(presentation), '')))
         id, btrim(nom) AS nom, nullif(btrim(dci), '') AS dci, nullif(btrim(forme), '') AS forme,
         nullif(btrim(presentation), '') AS presentation, nullif(btrim(classe), '') AS classe,
         CASE WHEN ppv > 0 THEN round(ppv::numeric, 2) END AS prix
  FROM import_medicament WHERE nullif(btrim(nom), '') IS NOT NULL
  ORDER BY lower(btrim(nom)), lower(coalesce(btrim(dci), '')), lower(coalesce(btrim(forme), '')), lower(coalesce(btrim(presentation), '')), id
) d ORDER BY id;

CREATE TEMP TABLE import_types_analyse (id int, nom_fr text, nom_en text, description text, code_fr text, code_en text) ON COMMIT DROP;
SELECT 'ANALYSE', jsonb_strip_nulls(jsonb_build_object('fr', nullif(btrim(nom_fr), ''), 'en', nullif(btrim(nom_en), ''))),
       jsonb_strip_nulls(jsonb_build_object('fr', nullif(btrim(code_fr), ''), 'en', nullif(btrim(code_en), '')))
FROM import_types_analyse WHERE nullif(btrim(nom_fr), '') IS NOT NULL ORDER BY id;

CREATE TEMP TABLE import_types_imagerie (id int, nom_fr text, nom_en text, description text, code_fr text, code_en text) ON COMMIT DROP;
SELECT 'IMAGERIE', jsonb_strip_nulls(jsonb_build_object('fr', nullif(btrim(nom_fr), ''), 'en', nullif(btrim(nom_en), ''))),
       jsonb_strip_nulls(jsonb_build_object('fr', nullif(btrim(code_fr), ''), 'en', nullif(btrim(code_en), '')))
FROM import_types_imagerie WHERE nullif(btrim(nom_fr), '') IS NOT NULL ORDER BY id;

